cd /workspace && cat > syntax/syntax.go <<'EOF'
// Package syntax converts a Go source file into a sequence of tokens suitable
// for clone detection. Each AST node is represented by a single integer token
// (based on its concrete type), with literal values ignored so that e.g. all
// integer literals compare equal.
package syntax

import (
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"reflect"
)

// Node is a single token emitted while walking the AST of a Go file.
type Node struct {
	Type   int
	Line   int
	Offset int
	Owns   int // number of following nodes that belong to this node's subtree (inclusive count is Owns+1)
}

// tokenNames enumerates AST node types we may encounter. Unknown types
// get a stable integer based on their reflect.Type string.
var typeIDs = map[string]int{}
var nextTypeID = 1

func typeID(n ast.Node) int {
	t := reflect.TypeOf(n).String()
	if id, ok := typeIDs[t]; ok {
		return id
	}
	id := nextTypeID
	nextTypeID++
	typeIDs[t] = id
	return id
}

// Parse parses the given Go file, returning its token sequence and the
// FileSet that can be used to resolve positions.
func Parse(filename string) ([]*Node, *token.FileSet, error) {
	src, err := ioutil.ReadFile(filename)
	if err != nil {
		return nil, nil, err
	}
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, filename, src, parser.ParseComments)
	if err != nil {
		return nil, fset, err
	}
	nodes := walk(file, fset)
	return nodes, fset, nil
}

// walk traverses the AST depth-first and emits one token per node.
func walk(root ast.Node, fset *token.FileSet) []*Node {
	var nodes []*Node
	var rec func(n ast.Node)
	rec = func(n ast.Node) {
		if n == nil {
			return
		}
		// Skip nil-valued interface leaves that can slip through reflection.
		rv := reflect.ValueOf(n)
		if rv.Kind() == reflect.Ptr && rv.IsNil() {
			return
		}
		pos := fset.Position(n.Pos())
		idx := len(nodes)
		node := &Node{
			Type:   typeID(n),
			Line:   pos.Line,
			Offset: pos.Offset,
		}
		nodes = append(nodes, node)
		// Visit children in source order.
		for _, child := range children(n) {
			rec(child)
		}
		nodes[idx].Owns = len(nodes) - idx - 1
	}
	rec(root)
	return nodes
}

// children returns the AST children of a node in source order.
func children(n ast.Node) []ast.Node {
	var out []ast.Node
	switch x := n.(type) {
	case *ast.File:
		// package name, imports, decls (in order they appear)
		out = append(out, x.Name)
		for _, d := range x.Decls {
			out = append(out, d)
		}
	case *ast.FuncDecl:
		if x.Recv != nil {
			out = append(out, x.Recv)
		}
		out = append(out, x.Name)
		out = append(out, x.Type)
		if x.Body != nil {
			out = append(out, x.Body)
		}
	case *ast.GenDecl:
		for _, s := range x.Specs {
			out = append(out, s)
		}
	case *ast.ImportSpec:
		if x.Name != nil {
			out = append(out, x.Name)
		}
		out = append(out, x.Path)
	case *ast.ValueSpec:
		for _, n := range x.Names {
			out = append(out, n)
		}
		if x.Type != nil {
			out = append(out, x.Type)
		}
		for _, v := range x.Values {
			out = append(out, v)
		}
	case *ast.TypeSpec:
		out = append(out, x.Name)
		if x.TypeParams != nil {
			out = append(out, x.TypeParams)
		}
		out = append(out, x.Type)
	case *ast.FieldList:
		for _, f := range x.List {
			out = append(out, f)
		}
	case *ast.Field:
		for _, n := range x.Names {
			out = append(out, n)
		}
		if x.Type != nil {
			out = append(out, x.Type)
		}
		if x.Tag != nil {
			out = append(out, x.Tag)
		}
	case *ast.FuncType:
		if x.TypeParams != nil {
			out = append(out, x.TypeParams)
		}
		if x.Params != nil {
			out = append(out, x.Params)
		}
		if x.Results != nil {
			out = append(out, x.Results)
		}
	case *ast.BlockStmt:
		for _, s := range x.List {
			out = append(out, s)
		}
	case *ast.ExprStmt:
		out = append(out, x.X)
	case *ast.AssignStmt:
		for _, e := range x.Lhs {
			out = append(out, e)
		}
		for _, e := range x.Rhs {
			out = append(out, e)
		}
	case *ast.IncDecStmt:
		out = append(out, x.X)
	case *ast.ReturnStmt:
		for _, r := range x.Results {
			out = append(out, r)
		}
	case *ast.DeferStmt:
		out = append(out, x.Call)
	case *ast.GoStmt:
		out = append(out, x.Call)
	case *ast.IfStmt:
		if x.Init != nil {
			out = append(out, x.Init)
		}
		out = append(out, x.Cond)
		out = append(out, x.Body)
		if x.Else != nil {
			out = append(out, x.Else)
		}
	case *ast.ForStmt:
		if x.Init != nil {
			out = append(out, x.Init)
		}
		if x.Cond != nil {
			out = append(out, x.Cond)
		}
		if x.Post != nil {
			out = append(out, x.Post)
		}
		out = append(out, x.Body)
	case *ast.RangeStmt:
		if x.Key != nil {
			out = append(out, x.Key)
		}
		if x.Value != nil {
			out = append(out, x.Value)
		}
		out = append(out, x.X)
		out = append(out, x.Body)
