		out = append(out, x.Key)
		out = append(out, x.Value)
	case *ast.ChanType:
		out = append(out, x.Value)
	case *ast.StructType:
		if x.Fields != nil {
			out = append(out, x.Fields)
		}
	case *ast.InterfaceType:
		if x.Methods != nil {
			out = append(out, x.Methods)
		}
	case *ast.Ident, *ast.BasicLit, *ast.Ellipsis, *ast.BadExpr, *ast.BadDecl, *ast.BadStmt, *ast.EmptyStmt, *ast.Comment, *ast.CommentGroup:
		// leaf nodes (no children we care about)
	}
	return out
}
