// Package syntax converts a Go source file into a sequence of tokens suitable
// for clone detection. Each AST node is represented by a single integer token
// (based on its concrete type), with literal values ignored so that e.g. all
// integer literals compare equal.
package syntax

import (
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"reflect"
)

// Node is a single token emitted while walking the AST of a Go file.
type Node struct {
	Type   int
	Line   int
	Offset int
	Owns   int // number of following nodes that belong to this node's subtree (inclusive count is Owns+1)
}

// tokenNames enumerates AST node types we may encounter. Unknown types
// get a stable integer based on their reflect.Type string.
var typeIDs = map[string]int{}
var nextTypeID = 1

func typeID(n ast.Node) int {
	t := reflect.TypeOf(n).String()
	if id, ok := typeIDs[t]; ok {
		return id
	}
	id := nextTypeID
	nextTypeID++
	typeIDs[t] = id
	return id
}

// Parse parses the given Go file, returning its token sequence and the
// FileSet that can be used to resolve positions.
func Parse(filename string) ([]*Node, *token.FileSet, error) {
	src, err := ioutil.ReadFile(filename)
	if err != nil {
		return nil, nil, err
	}
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, filename, src, parser.ParseComments)
	if err != nil {
		return nil, fset, err
	}
	nodes := walk(file, fset)
	return nodes, fset, nil
}

// walk traverses the AST depth-first and emits one token per node.
func walk(root ast.Node, fset *token.FileSet) []*Node {
	var nodes []*Node
	var rec func(n ast.Node)
	rec = func(n ast.Node) {
		if n == nil {
			return
		}
		// Skip nil-valued interface leaves that can slip through reflection.
		rv := reflect.ValueOf(n)
		if rv.Kind() == reflect.Ptr && rv.IsNil() {
			return
		}
		pos := fset.Position(n.Pos())
		idx := len(nodes)
		node := &Node{
			Type:   typeID(n),
			Line:   pos.Line,
			Offset: pos.Offset,
		}
		nodes = append(nodes, node)
		// Visit children in source order.
		for _, child := range children(n) {
			rec(child)
		}
		nodes[idx].Owns = len(nodes) - idx - 1
	}
	rec(root)
	return nodes
}

// children returns the AST children of a node in source order.
func children(n ast.Node) []ast.Node {
	var out []ast.Node
	switch x := n.(type) {
	case *ast.File:
		// package name, imports, decls (in order they appear)
		out = append(out, x.Name)
		for _, d := range x.Decls {
			out = append(out, d)
		}
	case *ast.FuncDecl:
		if x.Recv != nil {
			out = append(out, x.Recv)
		}
		out = append(out, x.Name)
		out = append(out, x.Type)
		if x.Body != nil {
			out = append(out, x.Body)
		}
	case *ast.GenDecl:
		for _, s := range x.Specs {
			out = append(out, s)
		}
	case *ast.ImportSpec:
		if x.Name != nil {
			out = append(out, x.Name)
		}
		out = append(out, x.Path)
	case *ast.ValueSpec:
		for _, n := range x.Names {
			out = append(out, n)
		}
		if x.Type != nil {
			out = append(out, x.Type)
		}
		for _, v := range x.Values {
			out = append(out, v)
		}
	case *ast.TypeSpec:
		out = append(out, x.Name)
		if x.TypeParams != nil {
			out = append(out, x.TypeParams)
		}
		out = append(out, x.Type)
	case *ast.FieldList:
		for _, f := range x.List {
			out = append(out, f)
		}
	case *ast.Field:
		for _, n := range x.Names {
			out = append(out, n)
		}
		if x.Type != nil {
			out = append(out, x.Type)
		}
		if x.Tag != nil {
			out = append(out, x.Tag)
		}
	case *ast.FuncType:
		if x.TypeParams != nil {
			out = append(out, x.TypeParams)
		}
		if x.Params != nil {
			out = append(out, x.Params)
		}
		if x.Results != nil {
			out = append(out, x.Results)
		}
	case *ast.BlockStmt:
		for _, s := range x.List {
			out = append(out, s)
		}
	case *ast.ExprStmt:
		out = append(out, x.X)
	case *ast.AssignStmt:
		for _, e := range x.Lhs {
			out = append(out, e)
		}
		for _, e := range x.Rhs {
			out = append(out, e)
		}
	case *ast.IncDecStmt:
		out = append(out, x.X)
	case *ast.ReturnStmt:
		for _, r := range x.Results {
			out = append(out, r)
		}
	case *ast.DeferStmt:
		out = append(out, x.Call)
	case *ast.GoStmt:
		out = append(out, x.Call)
	case *ast.IfStmt:
		if x.Init != nil {
			out = append(out, x.Init)
		}
		out = append(out, x.Cond)
		out = append(out, x.Body)
		if x.Else != nil {
			out = append(out, x.Else)
		}
	case *ast.ForStmt:
		if x.Init != nil {
			out = append(out, x.Init)
		}
		if x.Cond != nil {
			out = append(out, x.Cond)
		}
		if x.Post != nil {
			out = append(out, x.Post)
		}
		out = append(out, x.Body)
	case *ast.RangeStmt:
		if x.Key != nil {
			out = append(out, x.Key)
		}
		if x.Value != nil {
			out = append(out, x.Value)
		}
		out = append(out, x.X)
		out = append(out, x.Body)
	case *ast.SwitchStmt:
		if x.Init != nil {
			out = append(out, x.Init)
		}
		if x.Tag != nil {
			out = append(out, x.Tag)
		}
		out = append(out, x.Body)
	case *ast.TypeSwitchStmt:
		if x.Init != nil {
			out = append(out, x.Init)
		}
		out = append(out, x.Assign)
		out = append(out, x.Body)
	case *ast.SelectStmt:
		out = append(out, x.Body)
	case *ast.CaseClause:
		for _, e := range x.List {
			out = append(out, e)
		}
		for _, s := range x.Body {
			out = append(out, s)
		}
	case *ast.CommClause:
		if x.Comm != nil {
			out = append(out, x.Comm)
		}
		for _, s := range x.Body {
			out = append(out, s)
		}
	case *ast.SendStmt:
		out = append(out, x.Chan)
		out = append(out, x.Value)
	case *ast.BranchStmt:
		if x.Label != nil {
			out = append(out, x.Label)
		}
	case *ast.LabeledStmt:
		out = append(out, x.Label)
		out = append(out, x.Stmt)
	case *ast.DeclStmt:
		out = append(out, x.Decl)
	case *ast.BinaryExpr:
		out = append(out, x.X)
		out = append(out, x.Y)
	case *ast.UnaryExpr:
		out = append(out, x.X)
	case *ast.ParenExpr:
		out = append(out, x.X)
	case *ast.StarExpr:
		out = append(out, x.X)
	case *ast.SelectorExpr:
		out = append(out, x.X)
		out = append(out, x.Sel)
	case *ast.IndexExpr:
		out = append(out, x.X)
		out = append(out, x.Index)
	case *ast.IndexListExpr:
		out = append(out, x.X)
		for _, idx := range x.Indices {
			out = append(out, idx)
		}
	case *ast.SliceExpr:
		out = append(out, x.X)
		if x.Low != nil {
			out = append(out, x.Low)
		}
		if x.High != nil {
			out = append(out, x.High)
		}
		if x.Max != nil {
			out = append(out, x.Max)
		}
	case *ast.TypeAssertExpr:
		out = append(out, x.X)
		if x.Type != nil {
			out = append(out, x.Type)
		}
	case *ast.CallExpr:
		out = append(out, x.Fun)
		for _, a := range x.Args {
			out = append(out, a)
		}
	case *ast.CompositeLit:
		if x.Type != nil {
			out = append(out, x.Type)
		}
		for _, e := range x.Elts {
			out = append(out, e)
		}
	case *ast.KeyValueExpr:
		out = append(out, x.Key)
		out = append(out, x.Value)
	case *ast.FuncLit:
		out = append(out, x.Type)
		out = append(out, x.Body)
	case *ast.ArrayType:
		if x.Len != nil {
			out = append(out, x.Len)
		}
		out = append(out, x.Elt)
	case *ast.MapType:
		out = append(out, x.Key)
		out = append(out, x.Value)
	case *ast.ChanType:
		out = append(out, x.Value)
	case *ast.StructType:
		if x.Fields != nil {
			out = append(out, x.Fields)
		}
	case *ast.InterfaceType:
		if x.Methods != nil {
			out = append(out, x.Methods)
		}
	case *ast.Ident, *ast.BasicLit, *ast.Ellipsis, *ast.BadExpr, *ast.BadDecl, *ast.BadStmt, *ast.EmptyStmt, *ast.Comment, *ast.CommentGroup:
		// leaf nodes (no children we care about)
	}
	return out
}
