// Package suffixtree builds a suffix-array based data structure over a
// sequence of integer tokens and provides helpers for finding "clone groups" -
// maximal-depth repeated substrings with non-overlapping occurrences.
package suffixtree

import (
	"sort"
)

// Seq is a global sequence of tokens annotated with source positions.
// It is built by concatenating tokens from multiple files, each followed
// by a unique separator so that suffixes from one file do not spuriously
// match across file boundaries.
type Seq struct {
	tokens []int    // token IDs including unique per-file separators
	infos  []Info   // per-token info (may be nil for separators)
	fileIDs []int   // file index, or -1 for separator
}

// Info carries metadata for a single token used to reconstruct source
// locations of clone matches.
type Info struct {
	Line   int
	EndLine int
}

// New returns an empty Seq.
func New() *Seq { return &Seq{} }

// Append appends a file's tokens (and their associated infos) to the sequence.
// A unique separator token is added afterwards.
func (s *Seq) Append(fileID int, tokens []int, infos []Info) {
	for i, t := range tokens {
		s.tokens = append(s.tokens, t)
		s.infos = append(s.infos, infos[i])
		s.fileIDs = append(s.fileIDs, fileID)
	}
	// Unique separator: negative values keyed by fileID+1 guarantee each file
	// boundary has a distinct token that never matches anything else.
	sep := -(fileID + 2)
	s.tokens = append(s.tokens, sep)
	s.infos = append(s.infos, Info{})
	s.fileIDs = append(s.fileIDs, -1)
}

// Len returns the total length of the concatenated sequence.
func (s *Seq) Len() int { return len(s.tokens) }

// FileID returns the file index for a given global position, or -1 if the
// position is a separator.
func (s *Seq) FileID(pos int) int { return s.fileIDs[pos] }

// Info returns the info metadata for a given global position.
func (s *Seq) Info(pos int) Info { return s.infos[pos] }

// Match represents a clone group: a set of starting positions that all share
// a common prefix of length Depth.
type Match struct {
	Positions []int
	Depth     int
}

// buildSuffixArray returns the suffix array of s.tokens, sorted in ascending
// order of suffixes by integer-lexicographic comparison.
func (s *Seq) buildSuffixArray() []int {
	n := len(s.tokens)
	sa := make([]int, n)
	for i := range sa {
		sa[i] = i
	}
	tokens := s.tokens
	sort.Slice(sa, func(i, j int) bool {
		a, b := sa[i], sa[j]
		for a < n && b < n {
			if tokens[a] != tokens[b] {
				return tokens[a] < tokens[b]
			}
			a++
			b++
		}
		return a > b // longer suffix comes first if one is a prefix of another? Actually shorter suffixes should come first for standard SA. But with unique separators we never have prefix-prefix, so this doesn't matter.
	})
	return sa
}

// buildLCP constructs the LCP array using the Kasai algorithm variant.
// lcp[i] = length of common prefix of sa[i-1] and sa[i].
func (s *Seq) buildLCP(sa []int) []int {
	n := len(s.tokens)
	if n == 0 {
		return nil
	}
	rank := make([]int, n)
	for i, p := range sa {
		rank[p] = i
	}
	lcp := make([]int, n)
	h := 0
	tokens := s.tokens
	for i := 0; i < n; i++ {
		if rank[i] > 0 {
			j := sa[rank[i]-1]
			for i+h < n && j+h < n && tokens[i+h] == tokens[j+h] {
				h++
			}
			lcp[rank[i]] = h
			if h > 0 {
				h--
			}
		} else {
			h = 0
		}
	}
	return lcp
}

