// Package job contains file discovery and orchestration helpers.
package job

import (
	"bufio"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// CollectFiles collects the list of Go files to analyze given the user-supplied
// paths. If a path is a file, it is included unconditionally. If a path is a
// directory, it is walked recursively for *.go files. If vendor is false,
// directories named "vendor" are skipped.
func CollectFiles(paths []string, vendor bool) ([]string, error) {
	var files []string
	for _, p := range paths {
		info, err := os.Lstat(p)
		if err != nil {
			return nil, err
		}
		if !info.IsDir() {
			files = append(files, p)
			continue
		}
		err = filepath.Walk(p, func(path string, fi os.FileInfo, werr error) error {
			if werr != nil {
				return werr
			}
			if fi.IsDir() {
				if !vendor && fi.Name() == "vendor" {
					return filepath.SkipDir
				}
				return nil
			}
			if strings.HasSuffix(fi.Name(), ".go") {
				files = append(files, path)
			}
			return nil
		})
		if err != nil {
			return nil, err
		}
	}
	sort.Strings(files)
	return files, nil
}

// ReadFilesList reads file names from r, one per line.
func ReadFilesList(r io.Reader) ([]string, error) {
	var files []string
	sc := bufio.NewScanner(r)
	for sc.Scan() {
		name := strings.TrimSpace(sc.Text())
		if name == "" {
			continue
		}
		files = append(files, name)
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	return files, nil
}
EOF
echo "done"

