// Package printer contains output formatters for clone groups.
package printer

import (
	"fmt"
	"html"
	"io"
	"os"
	"sort"
	"strings"
)

// Clone represents a single clone occurrence.
type Clone struct {
	Filename string
	Line     int
	EndLine  int
	// Fragment is the raw source text of the clone (used for -html output).
	Fragment string
}

// Group is a set of clone occurrences that all share the same token sequence.
type Group []Clone

// Sort groups clones in the canonical output order: filename asc, then line asc.
func (g Group) canonSort() {
	sort.Slice(g, func(i, j int) bool {
		if g[i].Filename != g[j].Filename {
			return g[i].Filename < g[j].Filename
		}
		if g[i].Line != g[j].Line {
			return g[i].Line < g[j].Line
		}
		return g[i].EndLine < g[j].EndLine
	})
}

// PrintText prints the "default" textual format:
//
//	found N clones:
//	  path:startLine,endLine
//	  ...
//
// followed by the total count line.
func PrintText(w io.Writer, groups []Group) {
	for _, g := range groups {
		g.canonSort()
		fmt.Fprintf(w, "found %d clones:\n", len(g))
		for _, c := range g {
			fmt.Fprintf(w, "  %s:%d,%d\n", c.Filename, c.Line, c.EndLine)
		}
	}
	fmt.Fprintf(w, "\nFound total %d clone groups.\n", len(groups))
}

// PrintPlumbing prints the plumbing format:
//
//	file:a-b: duplicate of file:c-d
//
// linking each occurrence to the next one in the group cyclically.
func PrintPlumbing(w io.Writer, groups []Group) {
	for _, g := range groups {
		g.canonSort()
		n := len(g)
		for i, c := range g {
			n2 := g[(i+1)%n]
			fmt.Fprintf(w, "%s:%d-%d: duplicate of %s:%d-%d\n",
				c.Filename, c.Line, c.EndLine,
				n2.Filename, n2.Line, n2.EndLine)
		}
	}
}

// PrintHTML prints the HTML format with clone group headers and fragment
// <pre> blocks.
func PrintHTML(w io.Writer, groups []Group) {
	fmt.Fprintf(w, `<!DOCTYPE html>
<meta charset="utf-8"/>
<title>Duplicates</title>
<style>
	pre {
		background-color: #FFD;
		border: 1px solid #E2E2E2;
		padding: 1ex;
	}
</style>
`)
	for i, g := range groups {
		g.canonSort()
		fmt.Fprintf(w, "<h1>#%d found %d clones</h1>\n", i+1, len(g))
		for _, c := range g {
			fmt.Fprintf(w, "<h2>%s:%d</h2>\n", c.Filename, c.Line)
			fmt.Fprintf(w, "<pre>%s</pre>\n", html.EscapeString(strings.TrimRight(c.Fragment, "\n")))
		}
	}
}

// Fatalf writes a standard error message (matching Go's log.Fatalf format) and
// exits with status 1.
func Fatalf(format string, args ...interface{}) {
	// Using the default logger-style prefix would be simplest but we need to
	// be careful to match the "YYYY/MM/DD HH:MM:SS" prefix. We delegate to log.
	panic(fmt.Sprintf(format, args...))
}

var _ = os.Stderr
EOF
