  If the given path is a file, dupl will use it regardless of
  the file extension. If it is a directory, it will recursively
  search for *.go files in that directory.

  If no path is given, dupl will recursively search for *.go
  files in the current directory.

Flags:
  -files
    	read file names from stdin one at each line
  -html
    	output the results as HTML, including duplicate code fragments
  -plumbing
    	plumbing (easy-to-parse) output for consumption by scripts or tools
  -t, -threshold size
    	minimum token sequence size as a clone (default 15)
  -vendor
    	check files in vendor directory
  -v, -verbose
    	explain what is being done

Examples:
  dupl -t 100
    	Search clones in the current directory of size at least
    	100 tokens.
  dupl $(find app/ -name '*_test.go')
    	Search for clones in tests in the app directory.
  find app/ -name '*_test.go' |dupl -files
    	The same as above.
`

var (
	filesFlag    bool
	htmlFlag     bool
	plumbingFlag bool
	vendorFlag   bool
	verboseFlag  bool
	threshold    = 15
)

func usage() {
	fmt.Fprint(os.Stderr, usageText)
}

func main() {
	log.SetFlags(log.LstdFlags)
	log.SetPrefix("")

	fs := flag.NewFlagSet("dupl", flag.ExitOnError)
	fs.Usage = usage

	fs.BoolVar(&filesFlag, "files", false, "read file names from stdin one at each line")
	fs.BoolVar(&htmlFlag, "html", false, "output the results as HTML, including duplicate code fragments")
	fs.BoolVar(&plumbingFlag, "plumbing", false, "plumbing (easy-to-parse) output for consumption by scripts or tools")
	fs.BoolVar(&vendorFlag, "vendor", false, "check files in vendor directory")
	fs.BoolVar(&verboseFlag, "verbose", false, "explain what is being done")
	fs.BoolVar(&verboseFlag, "v", false, "explain what is being done")
	fs.IntVar(&threshold, "threshold", 15, "minimum token sequence as a clone")
	fs.IntVar(&threshold, "t", 15, "minimum token sequence as a clone")

	// Go's flag package writes to stderr by default when an unknown flag is
	// encountered. We want the same behaviour but using our custom usage.
	if err := fs.Parse(os.Args[1:]); err != nil {
		os.Exit(2)
	}

	if htmlFlag && plumbingFlag {
		log.Fatal("you can have either plumbing or HTML output")
	}

	args := fs.Args()

	var files []string
	var err error
	if filesFlag {
		files, err = job.ReadFilesList(os.Stdin)
		if err != nil {
			log.Println(err)
		}
		// Additional command-line arguments are also accepted in files mode.
		files = append(files, args...)
	} else {
		paths := args
		if len(paths) == 0 {
			paths = []string{"."}
		}
		files, err = job.CollectFiles(paths, vendorFlag)
		if err != nil {
			log.Println(err)
			if isFatal(err) {
				printEmpty()
				os.Exit(1)
			}
		}
	}
	sort.Strings(files)
	files = dedupStrings(files)

	// Parse each file and append tokens to the global sequence.
	seq := suffixtree.New()
	type fileData struct {
		filename string
		source   []byte
		offsets  []int // byte offset per token position
	}
	fileIdx := map[int]*fileData{}

	if verboseFlag {
		log.Println("Building suffix tree")
	}

	for _, f := range files {
		src, err := ioutil.ReadFile(f)
		if err != nil {
			log.Println(err)
			continue
		}
		nodes, _, perr := syntax.Parse(f)
		if perr != nil {
			log.Println(perr)
			continue
		}
		if len(nodes) == 0 {
			continue
		}
		tokens := make([]int, len(nodes))
		infos := make([]suffixtree.Info, len(nodes))
		offsets := make([]int, len(nodes))
		for i, n := range nodes {
			tokens[i] = n.Type
			// end line is computed lazily below
			infos[i] = suffixtree.Info{Line: n.Line}
			offsets[i] = n.Offset
		}
		// Fill EndLine: for each token, EndLine is the max Line of the
		// current token and all tokens that are part of its subtree.
		for i := len(nodes) - 1; i >= 0; i-- {
			n := nodes[i]
			endLine := n.Line
			if n.Owns > 0 {
				// Look at the subtree's last line by examining the last node.
				last := nodes[i+n.Owns]
				if last.Line > endLine {
					endLine = last.Line
				}
				// Also scan children to find max
				for k := i + 1; k <= i+n.Owns; k++ {
					if nodes[k].Line > endLine {
						endLine = nodes[k].Line
					}
				}
			}
			infos[i].EndLine = endLine
		}

		id := len(fileIdx)
		fileIdx[id] = &fileData{filename: f, source: src, offsets: offsets}
		seq.Append(id, tokens, infos)
	}

	if verboseFlag {
		log.Println("Searching for clones")
	}

	// Find clone groups.
	matches := seq.FindClones(threshold)

	// De-duplicate groups with identical occurrence sets.
	matches = dedupMatches(matches)

	// Build printer groups: for each match, translate positions to
	// (filename, line, endline, fragment) tuples.
	groups := make([]printer.Group, 0, len(matches))
	for _, m := range matches {
		var group printer.Group
		seen := map[string]bool{}
		for _, p := range m.Positions {
			fid := seq.FileID(p)
			if fid < 0 {
				continue
			}
			info := seq.Info(p)
			// last position in this match:
			lastPos := p + m.Depth - 1
			if lastPos >= seq.Len() {
				lastPos = seq.Len() - 1
			}
			lastInfo := seq.Info(lastPos)
			endLine := lastInfo.EndLine
			if endLine < info.Line {
				endLine = info.Line
			}
			fd := fileIdx[fid]
			// Extract fragment for HTML output
			startOff := fd.offsets[p-firstPosOfFile(seq, fid)]
			endOff := len(fd.source)
			if lastPos-firstPosOfFile(seq, fid) < len(fd.offsets)-1 {
				// end offset = offset of next token, if same file
				nextPos := lastPos + 1
				if nextPos < seq.Len() && seq.FileID(nextPos) == fid {
					endOff = fd.offsets[nextPos-firstPosOfFile(seq, fid)]
				}
			}
			if startOff > len(fd.source) {
				startOff = len(fd.source)
			}
			if endOff > len(fd.source) {
				endOff = len(fd.source)
			}
			fragment := string(fd.source[startOff:endOff])
			key := fmt.Sprintf("%s:%d-%d", fd.filename, info.Line, endLine)
			if seen[key] {
				// Still include duplicates to match dupl's behaviour, which
				// reports every occurrence of an AST position even if it
				// resolves to the same line range.
			}
			seen[key] = true
			group = append(group, printer.Clone{
				Filename: fd.filename,
				Line:     info.Line,
				EndLine:  endLine,
				Fragment: fragment,
			})
		}
		if len(group) >= 2 {
			groups = append(groups, group)
		}
	}

	// Sort groups: larger depth first (i.e., longer matches first).
	sort.SliceStable(groups, func(i, j int) bool {
		// Larger groups (more clones) first? Need to match dupl.
		// Our earlier tests suggested ordering by depth desc.
		// As a proxy, sort by len(group) desc then by first filename/line.
		if len(groups[i]) != len(groups[j]) {
			return len(groups[i]) > len(groups[j])
		}
		return false
	})

	var out = os.Stdout
	if htmlFlag {
		printer.PrintHTML(out, groups)
	} else if plumbingFlag {
		printer.PrintPlumbing(out, groups)
	} else {
		printer.PrintText(out, groups)
	}
}

func isFatal(err error) bool {
	msg := err.Error()
	return strings.Contains(msg, "no such file or directory") && strings.HasPrefix(msg, "lstat ")
}

func printEmpty() {
	if htmlFlag {
		printer.PrintHTML(os.Stdout, nil)
	} else if plumbingFlag {
		// nothing to print
	} else {
		fmt.Println()
		fmt.Println("Found total 0 clone groups.")
	}
}

// firstPosOfFile returns the global position of the first token of a file.
func firstPosOfFile(seq *suffixtree.Seq, fileID int) int {
	for i := 0; i < seq.Len(); i++ {
		if seq.FileID(i) == fileID {
			return i
		}
	}
	return -1
}

func dedupStrings(s []string) []string {
	out := s[:0]
	var prev string
	for i, v := range s {
		if i == 0 || v != prev {
			out = append(out, v)
			prev = v
		}
	}
	return out
}

func dedupMatches(m []suffixtree.Match) []suffixtree.Match {
	seen := map[string]bool{}
	out := m[:0]
	for _, match := range m {
		k := matchKey(match)
		if seen[k] {
			continue
		}
		seen[k] = true
		out = append(out, match)
	}
	return out
}

func matchKey(m suffixtree.Match) string {
	parts := make([]string, 0, len(m.Positions)+1)
	parts = append(parts, fmt.Sprintf("d=%d", m.Depth))
	positions := append([]int(nil), m.Positions...)
	sort.Ints(positions)
	for _, p := range positions {
		parts = append(parts, fmt.Sprintf("%d", p))
	}
	return strings.Join(parts, ",")
}
