// findClones finds all groups of duplicate subtree sequences.
// It iterates over contiguous sibling sequences in each file's AST,
// hashes them, and groups spans with matching hashes.
func findClones(filesData []fileData, threshold int) [][]span {
	type hashEntry struct {
		hash   string
		length int
	}
	bucket := map[string][]span{}

	for fi, fd := range filesData {
		// For each node, consider its subtree as a candidate span.
		// We also generate contiguous sibling-sequence spans at each level.
		nodes := fd.nodes
		// Precompute children index lists: for each node at index i, what are its direct children indices?
		childrenOf := make([][]int, len(nodes))
		var visit func(idx int)
		visit = func(idx int) {
			n := nodes[idx]
			if n.Owns == 0 {
				return
			}
			child := idx + 1
			endIdx := idx + n.Owns
			for child <= endIdx {
				childrenOf[idx] = append(childrenOf[idx], child)
				child += nodes[child].Owns + 1
			}
			for _, c := range childrenOf[idx] {
				visit(c)
			}
		}
		if len(nodes) > 0 {
			visit(0)
		}

		// For each node, emit a span covering its entire subtree.
		for i, n := range nodes {
			length := n.Owns + 1
			if length < threshold {
				continue
			}
			h := hashSubtree(nodes, i)
			s := span{
				file:    fd.name,
				fileID:  fi,
				start:   i,
				length:  length,
				line:    n.Line,
				endLine: lastLine(nodes, i),
				offStart: n.Offset,
				offEnd:   endOffset(nodes, i, len(fd.source)),
			}
			bucket[h] = append(bucket[h], s)
		}

		// For each parent node, also emit spans covering contiguous
		// sequences of >=2 children (but never the full children list, that's
		// covered by the parent itself).
		for i := range nodes {
			kids := childrenOf[i]
			if len(kids) < 2 {
				continue
			}
			for start := 0; start < len(kids); start++ {
				length := 0
				for end := start; end < len(kids); end++ {
					cLen := nodes[kids[end]].Owns + 1
					length += cLen
					// skip the single-child case (covered by subtree above)
					if end == start {
						continue
					}
					// skip full children list (covered by parent subtree itself)
					if start == 0 && end == len(kids)-1 {
						continue
					}
					if length < threshold {
						continue
					}
					h := hashChildren(nodes, kids, start, end)
					ci := nodes[kids[start]]
					s := span{
						file:    fd.name,
						fileID:  fi,
						start:   kids[start],
						length:  length,
						line:    ci.Line,
						endLine: lastLine(nodes, kids[end]),
						offStart: ci.Offset,
						offEnd:   endOffset(nodes, kids[end], len(fd.source)),
					}
					bucket[h] = append(bucket[h], s)
				}
			}
		}
	}

	// Filter: keep groups with >= 2 spans.
	var groups [][]span
	for _, spans := range bucket {
		if len(spans) < 2 {
			continue
		}
		// De-dup identical spans (same file, start, length)
		sort.Slice(spans, func(i, j int) bool {
			if spans[i].file != spans[j].file {
				return spans[i].file < spans[j].file
			}
			if spans[i].line != spans[j].line {
				return spans[i].line < spans[j].line
			}
			return spans[i].endLine < spans[j].endLine
		})
		dedup := spans[:0]
		var prev span
		for i, s := range spans {
			if i > 0 && s.file == prev.file && s.start == prev.start && s.length == prev.length {
				continue
			}
			dedup = append(dedup, s)
			prev = s
		}
		if len(dedup) < 2 {
			continue
		}
		groups = append(groups, dedup)
	}

	// Filter subsumed groups: if every span in group A is contained in a
	// span of group B with larger length, drop A.
	groups = filterSubsumed(groups)
	return groups
}

// filterSubsumed removes clone groups that are fully contained in larger groups.
func filterSubsumed(groups [][]span) [][]span {
	// Build an index from span (file, offset range) to group.
	// For each group, check whether all its spans are covered by another
	// group of strictly larger length.
	sort.SliceStable(groups, func(i, j int) bool {
		return groups[i][0].length > groups[j][0].length
	})
	// Greedy: for each span, track the largest group it belongs to.
	type key struct {
		file string
		off  int
		end  int
	}
	type assignment struct {
		groupIdx int
		length   int
	}
	owner := map[key]assignment{}
	accept := make([]bool, len(groups))
	for gi, grp := range groups {
		// If every span in grp is strictly contained in an already-emitted group, skip.
		allCovered := true
		for _, s := range grp {
			k := key{file: s.file, off: s.offStart, end: s.offEnd}
			_ = k
			if !isContained(owner, s) {
				allCovered = false
				break
			}
		}
		if allCovered {
			continue
		}
		accept[gi] = true
		for _, s := range grp {
			owner[key{file: s.file, off: s.offStart, end: s.offEnd}] = assignment{groupIdx: gi, length: s.length}
		}
	}
	out := make([][]span, 0, len(groups))
	for i, g := range groups {
		if accept[i] {
			out = append(out, g)
		}
	}
	return out
}

func isContained(owner map[string]struct{}, s span) bool { return false }

