		// We also generate contiguous sibling-sequence spans at each level.
		nodes := fd.nodes
		// Precompute children index lists: for each node at index i, what are its direct children indices?
		childrenOf := make([][]int, len(nodes))
		var visit func(idx int)
		visit = func(idx int) {
			n := nodes[idx]
			if n.Owns == 0 {
				return
			}
			child := idx + 1
			endIdx := idx + n.Owns
			for child <= endIdx {
				childrenOf[idx] = append(childrenOf[idx], child)
				child += nodes[child].Owns + 1
			}
			for _, c := range childrenOf[idx] {
				visit(c)
			}
		}
		if len(nodes) > 0 {
			visit(0)
		}

		// For each node, emit a span covering its entire subtree.
		for i, n := range nodes {
			length := n.Owns + 1
			if length < threshold {
				continue
			}
			h := hashSubtree(nodes, i)
			s := span{
				file:    fd.name,
				fileID:  fi,
				start:   i,
				length:  length,
				line:    n.Line,
				endLine: lastLine(nodes, i),
				offStart: n.Offset,
				offEnd:   endOffset(nodes, i, len(fd.source)),
			}
			bucket[h] = append(bucket[h], s)
		}

		// For each parent node, also emit spans covering contiguous
		// sequences of >=2 children (but never the full children list, that's
		// covered by the parent itself).
		for i := range nodes {
			kids := childrenOf[i]
			if len(kids) < 2 {
				continue
			}
			for start := 0; start < len(kids); start++ {
				length := 0
				for end := start; end < len(kids); end++ {
					cLen := nodes[kids[end]].Owns + 1
					length += cLen
					// skip the single-child case (covered by subtree above)
					if end == start {
						continue
					}
					// skip full children list (covered by parent subtree itself)
					if start == 0 && end == len(kids)-1 {
						continue
					}
					if length < threshold {
						continue
