// findClones finds all groups of duplicate subtree sequences.
// It iterates over contiguous sibling sequences in each file's AST,
// hashes them, and groups spans with matching hashes.
func findClones(filesData []fileData, threshold int) [][]span {
	type hashEntry struct {
		hash   string
		length int
	}
	bucket := map[string][]span{}

	for fi, fd := range filesData {
		// For each node, consider its subtree as a candidate span.
		// We also generate contiguous sibling-sequence spans at each level.
		nodes := fd.nodes
		// Precompute children index lists: for each node at index i, what are its direct children indices?
		childrenOf := make([][]int, len(nodes))
		var visit func(idx int)
		visit = func(idx int) {
			n := nodes[idx]
			if n.Owns == 0 {
				return
			}
			child := idx + 1
			endIdx := idx + n.Owns
			for child <= endIdx {
				childrenOf[idx] = append(childrenOf[idx], child)
				child += nodes[child].Owns + 1
			}
			for _, c := range childrenOf[idx] {
				visit(c)
			}
		}
		if len(nodes) > 0 {
			visit(0)
		}

		// For each node, emit a span covering its entire subtree.
		for i, n := range nodes {
			length := n.Owns + 1
			if length < threshold {
				continue
			}
			h := hashSubtree(nodes, i)
			s := span{
				file:    fd.name,
				fileID:  fi,
				start:   i,
				length:  length,
				line:    n.Line,
				endLine: lastLine(nodes, i),
				offStart: n.Offset,
				offEnd:   endOffset(nodes, i, len(fd.source)),
			}
			bucket[h] = append(bucket[h], s)
		}

		// For each parent node, also emit spans covering contiguous
		// sequences of >=2 children (but never the full children list, that's
		// covered by the parent itself).
		for i := range nodes {
			kids := childrenOf[i]
			if len(kids) < 2 {
				continue
			}
			for start := 0; start < len(kids); start++ {
				length := 0
				for end := start; end < len(kids); end++ {
					cLen := nodes[kids[end]].Owns + 1
					length += cLen
					// skip the single-child case (covered by subtree above)
					if end == start {
						continue
					}
					// skip full children list (covered by parent subtree itself)
					if start == 0 && end == len(kids)-1 {
						continue
					}
					if length < threshold {
						continue
					}
					h := hashChildren(nodes, kids, start, end)
					ci := nodes[kids[start]]
					s := span{
						file:    fd.name,
						fileID:  fi,
						start:   kids[start],
						length:  length,
						line:    ci.Line,
						endLine: lastLine(nodes, kids[end]),
						offStart: ci.Offset,
						offEnd:   endOffset(nodes, kids[end], len(fd.source)),
					}
					bucket[h] = append(bucket[h], s)
				}
			}
		}
	}

	// Filter: keep groups with >= 2 spans.
	var groups [][]span
	for _, spans := range bucket {
		if len(spans) < 2 {
			continue
		}
		// De-dup identical spans (same file, start, length)
		sort.Slice(spans, func(i, j int) bool {
			if spans[i].file != spans[j].file {
				return spans[i].file < spans[j].file
			}
			if spans[i].line != spans[j].line {
				return spans[i].line < spans[j].line
			}
			return spans[i].endLine < spans[j].endLine
		})
		dedup := spans[:0]
		var prev span
		for i, s := range spans {
			if i > 0 && s.file == prev.file && s.start == prev.start && s.length == prev.length {
				continue
			}
			dedup = append(dedup, s)
			prev = s
		}
		if len(dedup) < 2 {
			continue
		}
		groups = append(groups, dedup)
	}

	// Filter subsumed groups: if every span in group A is contained in a
	// span of group B with larger length, drop A.
	groups = filterSubsumed(groups)
	return groups
}

// filterSubsumed removes clone groups that are fully contained in larger groups.
func filterSubsumed(groups [][]span) [][]span {
	// Build an index from span (file, offset range) to group.
	// For each group, check whether all its spans are covered by another
	// group of strictly larger length.
	sort.SliceStable(groups, func(i, j int) bool {
		return groups[i][0].length > groups[j][0].length
	})
	// Greedy: for each span, track the largest group it belongs to.
	type key struct {
		file string
		off  int
		end  int
	}
	type assignment struct {
		groupIdx int
		length   int
	}
	owner := map[key]assignment{}
	accept := make([]bool, len(groups))
	for gi, grp := range groups {
		// If every span in grp is strictly contained in an already-emitted group, skip.
		allCovered := true
		for _, s := range grp {
			k := key{file: s.file, off: s.offStart, end: s.offEnd}
			_ = k
			if !isContained(owner, s) {
				allCovered = false
				break
			}
		}
		if allCovered {
			continue
		}
		accept[gi] = true
		for _, s := range grp {
			owner[key{file: s.file, off: s.offStart, end: s.offEnd}] = assignment{groupIdx: gi, length: s.length}
		}
	}
	out := make([][]span, 0, len(groups))
	for i, g := range groups {
		if accept[i] {
			out = append(out, g)
		}
	}
	return out
}

func isContained(owner map[string]struct{}, s span) bool { return false }

// The above placeholder signature isn't used; we override below.

func init() {
	// placeholder
}

func hashSubtree(nodes []*syntax.Node, i int) string {
	h := sha1.New()
	end := i + nodes[i].Owns + 1
	for k := i; k < end; k++ {
		var buf [8]byte
		v := uint32(nodes[k].Type)
		buf[0] = byte(v)
		buf[1] = byte(v >> 8)
		buf[2] = byte(v >> 16)
		buf[3] = byte(v >> 24)
		// Also include sibling-level break: owns info helps distinguish
		// shapes that would have the same token sequence.
		v2 := uint32(nodes[k].Owns)
		buf[4] = byte(v2)
		buf[5] = byte(v2 >> 8)
		buf[6] = byte(v2 >> 16)
		buf[7] = byte(v2 >> 24)
		h.Write(buf[:])
	}
	return hex.EncodeToString(h.Sum(nil))
}

func hashChildren(nodes []*syntax.Node, kids []int, start, end int) string {
	h := sha1.New()
	for i := start; i <= end; i++ {
		s := kids[i]
		e := s + nodes[s].Owns + 1
		for k := s; k < e; k++ {
			var buf [8]byte
			v := uint32(nodes[k].Type)
			buf[0] = byte(v)
			buf[1] = byte(v >> 8)
			buf[2] = byte(v >> 16)
			buf[3] = byte(v >> 24)
			v2 := uint32(nodes[k].Owns)
			buf[4] = byte(v2)
			buf[5] = byte(v2 >> 8)
			buf[6] = byte(v2 >> 16)
			buf[7] = byte(v2 >> 24)
			h.Write(buf[:])
		}
	}
	return hex.EncodeToString(h.Sum(nil))
}

func lastLine(nodes []*syntax.Node, i int) int {
	max := nodes[i].Line
	end := i + nodes[i].Owns + 1
	for k := i + 1; k < end; k++ {
		if nodes[k].Line > max {
			max = nodes[k].Line
		}
	}
	return max
}

func endOffset(nodes []*syntax.Node, i int, fileLen int) int {
	end := i + nodes[i].Owns + 1
	if end >= len(nodes) {
		return fileLen
	}
	return nodes[end].Offset
}

func collectFiles(paths []string, vendor bool) ([]string, error) {
	var files []string
	for _, p := range paths {
		info, err := os.Lstat(p)
		if err != nil {
			return nil, err
		}
		if !info.IsDir() {
			files = append(files, p)
			continue
		}
		err = filepath.Walk(p, func(path string, fi os.FileInfo, werr error) error {
			if werr != nil {
				return werr
			}
			if fi.IsDir() {
				if !vendor && fi.Name() == "vendor" {
					return filepath.SkipDir
				}
				return nil
			}
			if strings.HasSuffix(fi.Name(), ".go") {
				files = append(files, path)
			}
			return nil
		})
		if err != nil {
			return nil, err
		}
	}
	sort.Strings(files)
	return files, nil
}

func readFilesList(r io.Reader) ([]string, error) {
	var files []string
	sc := bufio.NewScanner(r)
	for sc.Scan() {
		name := strings.TrimSpace(sc.Text())
		if name == "" {
			continue
		}
		files = append(files, name)
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	return files, nil
}

func dedupStrings(s []string) []string {
	out := s[:0]
	var prev string
	for i, v := range s {
		if i == 0 || v != prev {
			out = append(out, v)
			prev = v
		}
	}
	return out
}

func printTotal(n int) {
	fmt.Println()
	fmt.Printf("Found total %d clone groups.\n", n)
}

func printText(w io.Writer, groups [][]span) {
	for _, g := range groups {
		fmt.Fprintf(w, "found %d clones:\n", len(g))
		for _, c := range g {
			fmt.Fprintf(w, "  %s:%d,%d\n", c.file, c.line, c.endLine)
		}
	}
	fmt.Fprintf(w, "\nFound total %d clone groups.\n", len(groups))
}

func printPlumbing(w io.Writer, groups [][]span) {
	for _, g := range groups {
		n := len(g)
		for i, c := range g {
			n2 := g[(i+1)%n]
			fmt.Fprintf(w, "%s:%d-%d: duplicate of %s:%d-%d\n",
				c.file, c.line, c.endLine,
				n2.file, n2.line, n2.endLine)
		}
	}
}

func printHTML(w io.Writer, groups [][]span, filesData []fileData) {
	fmt.Fprintf(w, `<!DOCTYPE html>
<meta charset="utf-8"/>
<title>Duplicates</title>
<style>
	pre {
		background-color: #FFD;
		border: 1px solid #E2E2E2;
		padding: 1ex;
	}
</style>
`)
	for i, g := range groups {
		fmt.Fprintf(w, "<h1>#%d found %d clones</h1>\n", i+1, len(g))
		for _, c := range g {
			fmt.Fprintf(w, "<h2>%s:%d</h2>\n", c.file, c.line)
			frag := ""
			for _, fd := range filesData {
				if fd.name == c.file {
					if c.offStart < len(fd.source) && c.offEnd <= len(fd.source) {
						frag = string(fd.source[c.offStart:c.offEnd])
					}
					break
				}
			}
			frag = strings.TrimRight(frag, "\n\t ")
			fmt.Fprintf(w, "<pre>%s</pre>\n", htmlEscape(frag))
		}
	}
}

func htmlEscape(s string) string {
	r := strings.NewReplacer(
		"&", "&amp;",
		"<", "&lt;",
		">", "&gt;",
		"\"", "&#34;",
		"'", "&#39;",
	)
	return r.Replace(s)
}
