func hashSubtree(nodes []*syntax.Node, i int) string {
	h := sha1.New()
	end := i + nodes[i].Owns + 1
	for k := i; k < end; k++ {
		var buf [8]byte
		v := uint32(nodes[k].Type)
		buf[0] = byte(v)
		buf[1] = byte(v >> 8)
		buf[2] = byte(v >> 16)
		buf[3] = byte(v >> 24)
		// Also include sibling-level break: owns info helps distinguish
		// shapes that would have the same token sequence.
		v2 := uint32(nodes[k].Owns)
		buf[4] = byte(v2)
		buf[5] = byte(v2 >> 8)
		buf[6] = byte(v2 >> 16)
		buf[7] = byte(v2 >> 24)
		h.Write(buf[:])
	}
	return hex.EncodeToString(h.Sum(nil))
}

func hashChildren(nodes []*syntax.Node, kids []int, start, end int) string {
	h := sha1.New()
	for i := start; i <= end; i++ {
		s := kids[i]
		e := s + nodes[s].Owns + 1
		for k := s; k < e; k++ {
			var buf [8]byte
			v := uint32(nodes[k].Type)
			buf[0] = byte(v)
			buf[1] = byte(v >> 8)
			buf[2] = byte(v >> 16)
			buf[3] = byte(v >> 24)
			v2 := uint32(nodes[k].Owns)
			buf[4] = byte(v2)
			buf[5] = byte(v2 >> 8)
			buf[6] = byte(v2 >> 16)
			buf[7] = byte(v2 >> 24)
			h.Write(buf[:])
		}
	}
	return hex.EncodeToString(h.Sum(nil))
}

func lastLine(nodes []*syntax.Node, i int) int {
	max := nodes[i].Line
	end := i + nodes[i].Owns + 1
	for k := i + 1; k < end; k++ {
		if nodes[k].Line > max {
			max = nodes[k].Line
		}
	}
	return max
}

func endOffset(nodes []*syntax.Node, i int, fileLen int) int {
	end := i + nodes[i].Owns + 1
	if end >= len(nodes) {
		return fileLen
	}
	return nodes[end].Offset
}

func collectFiles(paths []string, vendor bool) ([]string, error) {
	var files []string
	for _, p := range paths {
		info, err := os.Lstat(p)
		if err != nil {
			return nil, err
		}
		if !info.IsDir() {
			files = append(files, p)
			continue
		}
		err = filepath.Walk(p, func(path string, fi os.FileInfo, werr error) error {
			if werr != nil {
				return werr
			}
			if fi.IsDir() {
				if !vendor && fi.Name() == "vendor" {
					return filepath.SkipDir
				}
				return nil
			}
			if strings.HasSuffix(fi.Name(), ".go") {
				files = append(files, path)
			}
			return nil
		})
		if err != nil {
			return nil, err
		}
	}
	sort.Strings(files)
	return files, nil
}

func readFilesList(r io.Reader) ([]string, error) {
	var files []string
	sc := bufio.NewScanner(r)
	for sc.Scan() {
		name := strings.TrimSpace(sc.Text())
		if name == "" {
			continue
		}
		files = append(files, name)
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	return files, nil
}

func dedupStrings(s []string) []string {
	out := s[:0]
	var prev string
	for i, v := range s {
		if i == 0 || v != prev {
			out = append(out, v)
			prev = v
		}
	}
	return out
}

func printTotal(n int) {
	fmt.Println()
	fmt.Printf("Found total %d clone groups.\n", n)
}

func printText(w io.Writer, groups [][]span) {
	for _, g := range groups {
		fmt.Fprintf(w, "found %d clones:\n", len(g))
		for _, c := range g {
			fmt.Fprintf(w, "  %s:%d,%d\n", c.file, c.line, c.endLine)
		}
	}
	fmt.Fprintf(w, "\nFound total %d clone groups.\n", len(groups))
}

func printPlumbing(w io.Writer, groups [][]span) {
	for _, g := range groups {
		n := len(g)
		for i, c := range g {
			n2 := g[(i+1)%n]
			fmt.Fprintf(w, "%s:%d-%d: duplicate of %s:%d-%d\n",
				c.file, c.line, c.endLine,
				n2.file, n2.line, n2.endLine)
		}
	}
}

func printHTML(w io.Writer, groups [][]span, filesData []fileData) {
	fmt.Fprintf(w, `<!DOCTYPE html>
<meta charset="utf-8"/>
<title>Duplicates</title>
<style>
	pre {
		background-color: #FFD;
		border: 1px solid #E2E2E2;
		padding: 1ex;
	}
</style>
`)
	for i, g := range groups {
		fmt.Fprintf(w, "<h1>#%d found %d clones</h1>\n", i+1, len(g))
		for _, c := range g {
			fmt.Fprintf(w, "<h2>%s:%d</h2>\n", c.file, c.line)
			frag := ""
			for _, fd := range filesData {
				if fd.name == c.file {
					if c.offStart < len(fd.source) && c.offEnd <= len(fd.source) {
						frag = string(fd.source[c.offStart:c.offEnd])
					}
					break
				}
			}
			frag = strings.TrimRight(frag, "\n\t ")
			fmt.Fprintf(w, "<pre>%s</pre>\n", htmlEscape(frag))
		}
	}
}

func htmlEscape(s string) string {
	r := strings.NewReplacer(
		"&", "&amp;",
		"<", "&lt;",
		">", "&gt;",
		"\"", "&#34;",
		"'", "&#39;",
	)
	return r.Replace(s)
}
